    private SvgIcons() {
    }

    /**
     * 生成自适应缩放的矢量图标节点
     *
     * @param key        图标键名（如 user, graduation-cap 等）
     * @param targetSize 目标宽高大小（单位 px）
     * @param styleClass 附加 CSS 类名
     * @return 图标容器 Node
     */
    public static Node createIcon(String key, double targetSize, String styleClass) {
        String pathString = PATH_DATA.getOrDefault(key, PATH_DATA.get("user"));
        SVGPath svgPath = new SVGPath();
        svgPath.setContent(pathString);
        if (styleClass != null && !styleClass.trim().isEmpty()) {
            svgPath.getStyleClass().add(styleClass);
        }

        // 各图标按自身 viewBox 等比缩放（默认 512，1024 图标单独登记）
        double viewBox = VIEWBOX_SIZES.getOrDefault(key, 512.0);
        double scale = targetSize / viewBox;
        svgPath.setScaleX(scale);
        svgPath.setScaleY(scale);

        Group group = new Group(svgPath);
        StackPane container = new StackPane(group);
        container.setMinSize(targetSize, targetSize);
        container.setPrefSize(targetSize, targetSize);
        container.setMaxSize(targetSize, targetSize);
        return container;
    }

    /**
     * 快捷生成默认尺寸 (16px) 的导航图标
     *
     * @param key 图标键名
     * @return 图标节点
     */
    public static Node createNavIcon(String key) {
        return createIcon(key, 16.0, "nav-icon");
    }
